mapper.select:
SELECT MOIM_TITLE
FROM TB_TRMA_MOIM_LIST
WHERE MOIM_ID = #{moimId}

mapper.update:
UPDATE TB_TRMA_CHAT_ROOM
SET TITLE = #{title}
    ,UPDATE_DT = CURRENT_TIMESTAMP
WHERE ROOM_ID = #{roomId}
    AND TITLE = #{roomId}

UPDATE TB_TRMA_CHAT_MEMBER
SET LAST_READ_DT = CURRENT_TIMESTAMP(3)
WHERE ROOM_ID = #{roomId}
AND USER_ID = #{userId}

UPDATE TB_TRMA_CHAT_MESSAGE
CONTENT_EN = #{contentEn}, CONTENT_JA = #{contentJa},
WHERE MESSAGE_ID = #{messageId}

UPDATE TB_TRMA_CHAT_ROOM
TITLE_EN = #{titleEn}, TITLE_JA = #{titleJa},
WHERE ROOM_ID = #{roomId}

mapper.delete:
DELETE FROM TB_TRMA_CHAT_MEMBER
WHERE ROOM_ID = #{roomId}
    AND USER_ID = #{userId}

mapper.update:
UPDATE TB_TRMA_CHAT_MEMBER
SET STATE_CD = 'K'
WHERE ROOM_ID = #{roomId}
    AND USER_ID = #{userId}

UPDATE TB_TRMA_CHAT_MEMBER
SET STATE_CD = 'A'
WHERE ROOM_ID = #{roomId}
    AND USER_ID = #{userId}
    AND STATE_CD = 'K'

